#!/usr/bin/env node

import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const sh6Root = path.resolve(scriptDir, '..');
const logCheckerRoot = process.env.LOGCHECKER_ROOT || path.resolve(sh6Root, '..', 'LogChecker');
const retrievedOn = '2026-08-26';

const [supportMarkdown, scoringSource, sh6SpecSource] = await Promise.all([
  readFile(path.join(logCheckerRoot, 'docs', 'contest-support.md'), 'utf8'),
  readFile(path.join(logCheckerRoot, 'src', 'core', 'scoring.ts'), 'utf8'),
  readFile(path.join(sh6Root, 'data', 'contest_scoring_spec.json'), 'utf8'),
]);

const sh6Spec = JSON.parse(sh6SpecSource);
const moduleRows = [...supportMarkdown.matchAll(/^\| `([^`]+)\.dll` \| ([^|]+) \| ([^|]+) \|$/gm)].map((match) => ({
  module: match[1],
  logchecker_status: match[2].trim(),
  logchecker_rule_name: match[3].trim(),
}));

if (moduleRows.length !== 137) {
  throw new Error(`Expected 137 LogChecker modules, found ${moduleRows.length}.`);
}

const scoringRulesStart = scoringSource.indexOf('export const scoringRules');
const recommendationsStart = scoringSource.indexOf('export function recommendedRuleId', scoringRulesStart);
const scoringRulesSource = scoringSource.slice(scoringRulesStart, recommendationsStart);
const recommendationSource = scoringSource.slice(recommendationsStart, scoringSource.indexOf('export function scoreCabrillo', recommendationsStart));
const logCheckerRules = [...scoringRulesSource.matchAll(/\bid:\s*"([^"]+)"[\s\S]{0,240}?\bname:\s*"([^"]+)"/g)].map((match) => ({
  id: match[1],
  name: match[2],
}));

const normalizedRuleName = (value) => String(value || '')
  .toLowerCase()
  .replace(/recovered|scoring|score|qso|points|behavior|calculation/g, '')
  .replace(/[^a-z0-9]+/g, '');

const sharedLogCheckerRules = new Map([
  ['digpa', 'dig-qso-party-recovered'],
  ['ft8ru', 'ft8-dx-recovered'],
  ['ldc', 'drcg-ww-rtty-recovered'],
]);

const ruleIdForModule = (row) => {
  if (sharedLogCheckerRules.has(row.module)) return sharedLogCheckerRules.get(row.module);
  const expected = normalizedRuleName(row.logchecker_rule_name);
  const matches = logCheckerRules.filter((rule) => normalizedRuleName(rule.name) === expected);
  if (matches.length !== 1) throw new Error(`Unable to resolve LogChecker rule for ${row.module}.dll (${row.logchecker_rule_name}).`);
  return matches[0].id;
};

const aliasesByRule = new Map();
for (const line of recommendationSource.split(/\r?\n/)) {
  const returnMatch = line.match(/return\s+"([^"]+)"/);
  if (!returnMatch) continue;
  const condition = line.slice(0, returnMatch.index);
  const aliases = [...condition.matchAll(/"([^"]+)"/g)].map((match) => match[1]);
  const current = aliasesByRule.get(returnMatch[1]) || new Set();
  aliases.forEach((alias) => current.add(alias));
  aliasesByRule.set(returnMatch[1], current);
}

