  markdownRows.join('\n') + '\n';

await mkdir(path.join(sh6Root, 'docs'), { recursive: true });
await Promise.all([
  writeFile(path.join(sh6Root, 'data', 'logchecker_scoring_coverage.json'), `${JSON.stringify(inventory, null, 2)}\n`),
  writeFile(path.join(sh6Root, 'docs', 'logchecker-scoring-coverage.md'), markdown),
]);

console.log(`Wrote ${records.length} module records (${summary['already supported in SH6 and left unchanged'] || 0} protected, ${summary['unsupported; official-rule research pending'] || 0} pending).`);
